properties.query:
let windowSize = 2h;
let ApprovedOps = _GetWatchlist('Approved_Operators_List') | project OperatorId;
let ApprovedCT = _GetWatchlist('Approved_CT_Transition_List') | project OperatorId;
let ApprovedCmds = _GetWatchlist('Approved_Mission_Command_List') | project CommandType;
let ApprovedArm = _GetWatchlist('Approved_Arm_Operator_List') | project OperatorId;
// S6: GCS 침해
let S6 =
    UAVOpAudit_CL
    | where TimeGenerated > ago(windowSize)
    | where EventType == 'login_failure'
        or (EventType == 'login_success' and Operator !in (ApprovedOps))
    | summarize S6_Count=count(), T1=min(TimeGenerated) by OperatorId;
// S13: CT 레벨 하향
let S13 =
    UAVCyberPosture_CL
    | where TimeGenerated > ago(windowSize)
    | where ChangedBy !in (ApprovedCT)
    | project T2=TimeGenerated, OperatorId=ChangedBy;
// S15: 야간 비인가 C4I 명령
let S15 =
    UAVC4I_CL
    | where TimeGenerated > ago(windowSize)
    | where hourofday(TimeGenerated) >= 23 or hourofday(TimeGenerated) < 5
    | where CommandType !in (ApprovedCmds)
    | project T3=TimeGenerated, OperatorId;
// S11: 비인가 무장
let S11 =
    UAVWeapon_CL
    | where TimeGenerated > ago(windowSize)
    | where EventType in ('arm','fire')
    | where OperatorId !in (ApprovedArm)
    | project T4=TimeGenerated, OperatorId, WeaponId;
S6
| join kind=inner (S13) on OperatorId
| where T2 >= T1 and T2 <= T1 + 60m
| join kind=inner (S15) on OperatorId
| where T3 >= T2 and T3 <= T2 + 60m
| join kind=inner (S11) on OperatorId
| where T4 >= T3 and T4 <= T3 + 30m
| extend CampaignType = "C1_GCS침해_CT하향_야간C4I_무장"
| extend StepSummary = strcat("S6@", tostring(T1), " → S13@", tostring(T2), " → S15@", tostring(T3), " → S11@", tostring(T4))
| extend Severity = "High"
| project T1, T2, T3, T4, OperatorId, WeaponId, CampaignType, StepSummary, Severity
